#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "adi.h"

/* Include the Exo-generated kernel header. */
#include "generated/adi/adi.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	u[i][j] =  (DATA_TYPE)(i + n-j) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static 
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n)) 
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("u");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, u[i][j]);
    }
  POLYBENCH_DUMP_END("u");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

@proc
def kernel_adi(
    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,
    q: DATA_TYPE[n, n] @ DRAM,
):
    # Ensure we have an interior region to update.
    assert n > 2

    # Coefficients of the tridiagonal systems.
    a: DATA_TYPE
    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE

    # Precomputed constants to avoid recomputing 1 + 2*a and 1 + 2*d
    # inside the innermost loops.
    one_plus_2a: DATA_TYPE
    one_plus_2d: DATA_TYPE

    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d

    one_plus_2a = 1.0 + 2.0 * a
    one_plus_2d = 1.0 + 2.0 * d

    for t in seq(1, tsteps + 1):

        # Column sweep: for each column i, solve a tridiagonal system
        # along the j dimension to update v(:, i). Each column is
        # independent, so we will parallelize this i loop.
        for i in seq(1, n - 1):
            v[0, i] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = v[0, i]

            # Forward sweep in j direction.
            for j in seq(1, n - 1):
                p[i, j] = -c / (a * p[i, j - 1] + b)
                q[i, j] = (
                    -d * u[j, i - 1]
                    + one_plus_2d * u[j, i]
                    - f * u[j, i + 1]
                    - a * q[i, j - 1]
                ) / (a * p[i, j - 1] + b)

            # Back substitution in j direction.
            v[n - 1, i] = 1.0
            for j in seq(1, n - 1):
                v[n - 1 - j, i] = (
                    p[i, n - 1 - j] * v[n - j, i]
                    + q[i, n - 1 - j]
                )

        # Row sweep: for each row i, solve a tridiagonal system along
        # the j dimension to update u(i, :). Again, each row is
        # independent, so we parallelize this i loop as well.
        for i in seq(1, n - 1):
            u[i, 0] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = u[i, 0]

            # Forward sweep in j direction.
            for j in seq(1, n - 1):
                p[i, j] = -f / (d * p[i, j - 1] + e)
                q[i, j] = (
                    -a * v[i - 1, j]
                    + one_plus_2a * v[i, j]
                    - c * v[i + 1, j]
                    - d * q[i, j - 1]
                ) / (d * p[i, j - 1] + e)

            # Back substitution in j direction.
            u[i, n - 1] = 1.0
            for j in seq(1, n - 1):
                u[i, n - 1 - j] = (
                    p[i, n - 1 - j] * u[i, n - j]
                    + q[i, n - 1 - j]
                )

