    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,
    q: DATA_TYPE[n, n] @ DRAM,
