    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE

    # Extra scalars used to reduce FLOPs inside the inner loops.
    one_plus_2a: DATA_TYPE
    one_plus_2d: DATA_TYPE

    # Per-iteration denominators reused in p/q updates to avoid
    # recomputing (a * p + b) and (d * p + e) twice each time.
