            p[i, 0] = 0.0
            q[i, 0] = v[0, i]

            # Forward sweep in j (Thomas algorithm).
            for j in seq(1, n - 1):
                # Common denominator for both p[i, j] and q[i, j].
                denom_col = a * p[i, j - 1] + b

                p[i, j] = -c / denom_col
                q[i, j] = (
                    -d * u[j, i - 1]
                    + one_plus_2d * u[j, i]
                    - f * u[j, i + 1]
                    - a * q[i, j - 1]
                ) / denom_col

            # Backward substitution in j.
            v[n - 1, i] = 1.0
            for j in seq(1, n - 1):
                v[n - 1 - j, i] = (
                    p[i, n - 1 - j] * v[n - j, i]
                    + q[i, n - 1 - j]
                )

