            u[i, n - 1] = 1.0
            for j in seq(1, n - 1):
                u[i, n - 1 - j] = (
                    p[i, n - 1 - j] * u[i, n - j]
                    + q[i, n - 1 - j]
                )


# ----------------------------------------------------------------------
# Scheduling / Optimization
# ----------------------------------------------------------------------

kernel_adi_opt = kernel_adi_base

# 1) Parallelize the outer i-loop of the column sweep.
#    Each column's tridiagonal solve is independent given u, so
#    Exo's dependence analysis can safely parallelize this loop.
col_i = kernel_adi_opt.find_loop("i")
kernel_adi_opt = parallelize_loop(kernel_adi_opt, col_i)

